const d = $input.first().json || {};

function extraerTexto(valor, profundidad = 0) {
  if (
    profundidad > 5 ||
    valor === null ||
    valor === undefined
  ) return '';

  if (typeof valor === 'string') return valor;

  if (
    typeof valor === 'number' ||
    typeof valor === 'boolean'
  ) return String(valor);

  if (Array.isArray(valor)) {
    return valor
      .map(item => extraerTexto(item, profundidad + 1))
      .filter(Boolean)
      .join('\n\n');
  }

  if (typeof valor === 'object') {
    const claves = [
      'field_value',
      'content',
      'text',
      'message',
      'mensaje',
      'response',
      'output',
      'data',
    ];

    for (const clave of claves) {
      if (
        !Object.prototype.hasOwnProperty.call(valor, clave)
      ) continue;

      const texto = extraerTexto(
        valor[clave],
        profundidad + 1
      ).trim();

      if (texto) return texto;
    }
  }

  return '';
}

let texto = extraerTexto(d.output).trim();
texto = texto.replace(/\bno (?:cuenta con|incluye|tiene) (?:un |el )?recurso(?: de)?[ _]agua\b/gi, 'No cuenta con jacuzzi');

if (!texto) {
  throw new Error(
    'No existe contenido en $json.output para ManyChat'
  );
}

// Las pruebas de este envío mostraron que la respuesta de cercanía llega sin URLs de Maps.
// Este filtro solo afecta a respuestas de cercanía/trayecto; no elimina enlaces de pago.
const normalizarCercania = valor => String(valor ?? '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const normalCercania = normalizarCercania(texto);
const pasosCercania = Array.isArray(d.intermediateSteps) ? d.intermediateSteps : [];
const esRespuestaCercania = d.tipo_respuesta === 'sucursal_mas_cercana'
  || pasosCercania.some(paso => paso?.action?.tool === 'Sucursal_Mas_Cercana')
  || /\b(?:mas cercan[ao]s?|mas cerca|mas proxim[ao]s?|menor distancia|menor tiempo de (?:traslado|trayecto)|comparacion de (?:distancias|trayectos))\b/.test(normalCercania)
  || (/\b\d+(?:[.,]\d+)?\s*(?:km|kilometros?)\b/.test(normalCercania)
      && /\b(?:sucursal|sucursales|trayecto|traslado|google maps)\b/.test(normalCercania));

function esUrlGoogleMaps(valor) {
  return /^(?:https?:\/\/)?(?:maps\.app\.goo\.gl(?:\/|$)|goo\.gl\/maps(?:\/|$)|maps\.google\.(?:com|com\.mx)(?:[/?#]|$)|(?:www\.)?google\.(?:com|com\.mx)\/maps(?:[/?#]|$))/i.test(String(valor).trim());
}

if (esRespuestaCercania) {
  // Primero los enlaces con etiqueta, para no dejar texto como «Ver mapa» sin destino.
  texto = texto.replace(/\[([^\]\n]*)\]\((https?:\/\/[^\s)]+)(?:\s+"[^"]*")?\)/gi,
    (completo, etiqueta, url) => esUrlGoogleMaps(url) ? '' : completo);
  texto = texto.replace(/<a\b[^>]*\bhref\s*=\s*["']([^"']+)["'][^>]*>[\s\S]*?<\/a>/gi,
    (completo, url) => esUrlGoogleMaps(url) ? '' : completo);
  texto = texto.replace(/<(https?:\/\/[^\s<>]+)>/gi,
    (completo, url) => esUrlGoogleMaps(url) ? '' : completo);
  texto = texto.replace(/https?:\/\/[^\s<>"']+/gi,
    url => esUrlGoogleMaps(url) ? '' : url);
  // También cubre un enlace de Maps escrito sin protocolo; los demás dominios quedan intactos.
  texto = texto.replace(/(^|[\s(])((?:maps\.app\.goo\.gl\/|goo\.gl\/maps\/|maps\.google\.(?:com|com\.mx)\/|(?:www\.)?google\.(?:com|com\.mx)\/maps\/)[^\s<>"']*)/gi,
    (completo, prefijo, url) => esUrlGoogleMaps(url) ? prefijo : completo);
  // Suprime únicamente las etiquetas vacías. La dirección escrita nunca se elimina.
  texto = texto
    .replace(/\r\n?/g, '\n')
    .replace(/^[ \t*_]*(?:[ðŸ“ðŸ—º️ðŸ”—ðŸš—-]+[ \t*_]*)?(?:ruta(?: en google maps)?|mapa(?: en google maps)?|google maps|maps|ubicacion|ubicación|enlace(?: de (?:mapa|ruta|google maps))?|ver (?:ruta|mapa)|c[oó]mo llegar)[ \t*_]*[:\-]?[ \t*_.,;!]*$/gmi, '')
    .replace(/^[ \t]*[()<>]+[ \t]*$/gm, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  if (!texto) throw new Error('RESPUESTA_CERCANIA_SIN_TEXTO: falta la sucursal y dirección escrita para responder.');
}


// Limpiar Markdown y espacios innecesarios.
texto = texto
  .replace(/\r\n?/g, '\n')
  .replace(/```[\w-]*\n?/g, '')
  .replace(/\*+/g, '')
  .replace(/__/g, '')
  .replace(/^\s*#{1,6}\s*/gm, '')
  .replace(/^\s*Agent-\s*/gim, '')
  .replace(/[ \t]+\n/g, '\n')
  .replace(/\n[ \t]+/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// El cierre contextual lo redacta Sara. No añadir preguntas automáticas.

const MAX_BYTES = 900;

// Medición UTF-8 sin depender de Buffer o TextEncoder.
function medirBytes(valor) {
  let total = 0;

  for (const caracter of valor) {
    const codigo = caracter.codePointAt(0);

    if (codigo <= 0x7f) total += 1;
    else if (codigo <= 0x7ff) total += 2;
    else if (codigo <= 0xffff) total += 3;
    else total += 4;
  }

  return total;
}

function buscarCorteNatural(valor) {
  const total = medirBytes(valor);
  const objetivo = total / 2;

  const patrones = [
    /\n{2,}/g,
    /\n/g,
    /[.!?]\s+/g,
    /[;:]\s+/g,
    /,\s+/g,
    /\s+/g,
  ];

  for (const patron of patrones) {
    const candidatos = [];
    let coincidencia;

    while (
      (coincidencia = patron.exec(valor)) !== null
    ) {
      const posicion =
        coincidencia.index + coincidencia[0].length;

      const izquierda = valor
        .slice(0, posicion)
        .trim();

      const derecha = valor
        .slice(posicion)
        .trim();

      if (
        izquierda &&
        derecha &&
        medirBytes(izquierda) <= MAX_BYTES &&
        medirBytes(derecha) <= MAX_BYTES
      ) {
        candidatos.push({
          posicion,
          distancia: Math.abs(
            medirBytes(izquierda) - objetivo
          ),
        });
      }
    }

    if (candidatos.length) {
      candidatos.sort(
        (a, b) => a.distancia - b.distancia
      );

      return candidatos[0].posicion;
    }
  }

  return null;
}

function corteSeguroPorBytes(valor) {
  let bytes = 0;
  let posicion = 0;

  for (const caracter of valor) {
    const peso = medirBytes(caracter);

    if (bytes + peso > MAX_BYTES) break;

    bytes += peso;
    posicion += caracter.length;
  }

  return posicion;
}

const totalBytes = medirBytes(texto);
let partes;

if (totalBytes <= MAX_BYTES) {
  partes = [texto];
} else {
  if (totalBytes > MAX_BYTES * 2) {
    throw new Error(
      `El mensaje ocupa ${totalBytes} bytes y no cabe ` +
      `en Parte 1 y Parte 2. Reduzca la respuesta a ` +
      `${MAX_BYTES * 2} bytes como máximo.`
    );
  }

  const corte =
    buscarCorteNatural(texto) ??
    corteSeguroPorBytes(texto);

  const parte1 = texto
    .slice(0, corte)
    .trim();

  const parte2 = texto
    .slice(corte)
    .trim();

  if (!parte1 || !parte2) {
    throw new Error(
      'No fue posible dividir el mensaje para ManyChat'
    );
  }

  partes = [parte1, parte2];
}

const campos = partes.map(
  (fieldValue, index) => ({
    field_name: `Parte ${index + 1}`,
    field_value: fieldValue,
  })
);

// Evita conservar un mapa de una respuesta anterior en el segundo campo.
if (esRespuestaCercania && campos.length === 1) {
  campos.push({ field_name: 'Parte 2', field_value: '' });
}

return [{
  json: {
    ...d,
    output: {
      data: campos,
    },
  },
}];

return [{
  json: {
    ...$json,
    count: $runIndex + 1
  }
}];

// El turno puede traer varias capturas (por ejemplo un comprobante de dos páginas).
// Se clasifica CADA una y se conserva la que sí es comprobante y trae más datos.
const entradas = $input.all();
const imagenes = $('Clasificar archivo descargado').all()
  .map((item) => item.json ?? {})
  .filter((json) => json.es_imagen_comprobante === true);
let origenRespaldo = {};
try {
  origenRespaldo = $('Detectar imagen ManyChat2').first().json ?? {};
} catch {
  origenRespaldo = {};
}

function buscar(v, n = 0) {
  if (n > 10 || v == null) return null;
  if (typeof v === 'string') { try { return buscar(JSON.parse(v.replace(/^```(?:json)?\s*|\s*```$/g, '')), n + 1); } catch { return null; } }
  if (typeof v === 'object' && !Array.isArray(v) && ('es_imagen_relacionada_pago' in v || 'es_comprobante_pago' in v)) return v;
  for (const x of Object.values(v)) { const r = buscar(x, n + 1); if (r) return r; }
  return null;
}

function puntajeComprobante(j) {
  let p = 0;
  if (Number(j.monto_pago) > 0) p += 100;
  if (String(j.clave_rastreo ?? '').trim()) p += 50;
  if (String(j.numero_referencia ?? '').trim()) p += 20;
  if (String(j.cuenta_beneficiaria_visible ?? j.cuenta_beneficiaria ?? '').trim()) p += 10;
  if (String(j.banco_emisor ?? '').trim()) p += 5;
  if (String(j.banco_receptor ?? '').trim()) p += 5;
  if (String(j.nombre_beneficiario ?? '').trim()) p += 3;
  return p + Number(j.confianza_pago ?? 0);
}

const clasificados = [];
for (let indice = 0; indice < entradas.length; indice++) {
  const respuesta = entradas[indice].json ?? {};
  const origen = imagenes[indice] ?? origenRespaldo;
  const c = buscar(respuesta) || {};
  const datos = c.datos_pago && typeof c.datos_pago === 'object' ? c.datos_pago : c;
  const txt = (v) => v == null || /^(null|undefined)$/i.test(String(v).trim()) ? '' : String(v).trim();
  let confianza = Number(c.confianza || 0); if (confianza > 1) confianza /= 100;
  const monto = typeof datos.monto_pago === 'number' ? datos.monto_pago : Number(txt(datos.monto_pago).replace(/MXN|\$|,|\s/gi, ''));
  const visible = txt(datos.cuenta_beneficiaria_visible || datos.cuenta_beneficiaria);
  const digitos = visible.replace(/\D/g, '');
  const ocr = {};
  for (const key of ['fecha_pago', 'clave_rastreo', 'numero_referencia', 'banco_emisor', 'banco_receptor', 'nombre_beneficiario', 'nombre_ordenante', 'concepto_pago', 'numero_comprobante', 'estado_pago_visible', 'tipo_cuenta_beneficiaria', 'moneda_pago']) ocr[key] = txt(datos[key]);
  ocr.clave_rastreo = ocr.clave_rastreo.replace(/\s/g, '');
  ocr.cuenta_beneficiaria_visible = visible;
  ocr.cuenta_beneficiaria_enmascarada = datos.cuenta_beneficiaria_enmascarada === true || /[*xX⬢â—]/.test(visible);
  ocr.cuenta_beneficiaria = !ocr.cuenta_beneficiaria_enmascarada && digitos.length === 18 ? digitos : '';
  ocr.ultimos_4_beneficiario = /\d{4}\s*$/.test(visible) ? digitos.slice(-4) : '';
  ocr.monto_pago = Number.isFinite(monto) && monto > 0 ? monto : null;
  ocr.referencia_bancaria_identificada = datos.referencia_bancaria_identificada === true;
  const tipo = txt(c.tipo || datos.tipo || 'no_pago').toLowerCase();
  const esStripe = tipo === 'stripe' || /\bstripe\b|checkout\.stripe/.test([tipo, ...(Array.isArray(c.senales) ? c.senales : []), c.motivo].join(' ').toLowerCase());
  // Evidencia de una operación ya intentada: importe visible o leído, más alguna señal
  // bancaria (estado, referencia, clave de rastreo, folio o institución financiera).
  const montoLeido = Number.isFinite(monto) && monto > 0;
  const hayRastro = Boolean(ocr.clave_rastreo || ocr.numero_referencia || ocr.numero_comprobante);
  const montoPresente = c.monto_visible === true || montoLeido;
  const senalOperacion = c.estado_transaccion_visible === true || c.referencia_operacion_visible === true || c.entidad_financiera_visible === true || hayRastro;
  const evidencia = montoPresente && senalOperacion;
  const evidenciaStripe = esStripe && montoPresente && (c.estado_transaccion_visible === true || /pagado|pago|confirm|gracias/.test([...(Array.isArray(c.senales) ? c.senales : []), c.motivo].join(' ').toLowerCase()));
  // Una promoción o Gift Card tiene su propia ruta: nunca se convierte en comprobante.
  const categoriaComercial = confianza >= 0.82 && ['promocion', 'gift_card'].includes(String(c.categoria_imagen ?? '')) ? String(c.categoria_imagen) : '';
  const reconocido = !categoriaComercial && (c.es_imagen_relacionada_pago === true || c.es_comprobante_pago === true) && confianza >= 0.82 && (evidencia || evidenciaStripe);
  clasificados.push({
    json: {
      ...origen, ...ocr, ocr,
      es_imagen_relacionada_pago: reconocido,
      es_archivo_relacionado_pago: reconocido,
      confianza_pago: confianza,
      tipo_imagen_pago: tipo,
      es_comprobante_stripe: reconocido && esStripe,
      senales_pago: Array.isArray(c.senales) ? c.senales : [],
      motivo_clasificacion: txt(c.motivo),
      categoria_imagen: reconocido ? 'comprobante' : (categoriaComercial || 'otra'),
      promocion: c.promocion && typeof c.promocion === 'object' ? c.promocion : {},
      gift_card: c.gift_card && typeof c.gift_card === 'object' ? c.gift_card : {},
    },
  });
}

const reconocidos = clasificados.filter((item) => item.json.es_imagen_relacionada_pago === true);
const candidatos = reconocidos.length ? reconocidos : clasificados;
const elegido = candidatos.length
  ? [...candidatos].sort((a, b) => puntajeComprobante(b.json) - puntajeComprobante(a.json))[0].json
  : {};
return [{
  json: {
    ...elegido,
    adjuntos_analizados: clasificados.length,
    adjuntos_reconocidos_como_pago: reconocidos.length,
    adjuntos_analizados_detalle: clasificados.map((item) => ({
      media_url: item.json.media_url ?? '',
      es_pago: item.json.es_imagen_relacionada_pago === true,
      monto_pago: item.json.monto_pago ?? null,
      clave_rastreo: item.json.clave_rastreo ?? '',
      cuenta_beneficiaria_visible: item.json.cuenta_beneficiaria_visible ?? '',
      motivo: item.json.motivo_clasificacion ?? '',
    })),
    comprobante_elegido_de_varios_adjuntos: clasificados.length > 1,
  },
}];

const d = $input.first().json ?? {};
const esPago = d.es_imagen_relacionada_pago === true;
const esStripe = d.es_comprobante_stripe === true || String(d.tipo_imagen_pago ?? '').trim().toLowerCase() === 'stripe';
// Solo el comprobante cuyo banco EMISOR (membrete o logotipo legible) es BBVA se comprueba
// manualmente y sin pedirle datos al cliente. Si el emisor no se distingue (PDF ilegible,
// imagen borrosa o membrete ausente) se piden los datos como con cualquier otro banco.
const emisorBBVA = String(d.banco_emisor ?? '').trim();
const pagoBBVA = esPago && !esStripe && /bbva|bancomer/i.test(emisorBBVA);
// Folio de operación hacia nuestra cuenta, aunque el documento no muestre el banco:
// tampoco se le pide nada al cliente, lo revisa el equipo (aprobación manual).
const folioDigPendiente = String(d.numero_comprobante ?? '').replace(/\D/g, '');
const refDigPendiente = String(d.numero_referencia ?? '').replace(/\D/g, '');
// Clave de rastreo SPEI: puede ser alfanumérica (Banorte: 3843CP02202609265818058072), así
// que se conserva tal cual. Si el documento YA la trae, nunca se le vuelve a pedir al cliente.
const rastreoPendiente = String(d.clave_rastreo ?? '').replace(/\s/g, '');
const folioOperacionPendiente = folioDigPendiente.length >= 4
  ? folioDigPendiente
  : (rastreoPendiente.length >= 8 ? rastreoPendiente : (refDigPendiente.length >= 8 ? refDigPendiente : ''));
const destinoDigPendiente = String(d.cuenta_beneficiaria_visible ?? d.cuenta_beneficiaria ?? '').replace(/\D/g, '');
const destinoEsNuestroPendiente = destinoDigPendiente.length >= 4 &&
  ('0487509553'.endsWith(destinoDigPendiente) || '012225004875095530'.endsWith(destinoDigPendiente));
const aprobacionManualPorFolioPendiente = esPago && !esStripe && folioOperacionPendiente !== '' &&
  destinoEsNuestroPendiente && Number(d.monto_pago) > 0 &&
  !/fallid|rechaz|cancelad|devuelt|no realiz|no complet/.test(String(d.estado_pago_visible ?? '').toLowerCase() + ' ' + String(d.tipo_imagen_pago ?? '').toLowerCase());
// El comprobante ya trae con qué identificarse (clave de rastreo o folio de operación):
// jamás se le piden datos al cliente. Se registra y lo revisa el equipo o Banxico.
const comprobanteFallidoPendiente = /fallid|rechaz|cancelad|devuelt|no realiz|no complet/.test(String(d.estado_pago_visible ?? '').toLowerCase() + ' ' + String(d.tipo_imagen_pago ?? '').toLowerCase());
// La clave de rastreo viene IMPRESA en el documento: volver a pedirla es absurdo, así que
// el caso "clave visible" manda sobre cualquier otro para elegir el mensaje al cliente.
const claveEnDocumentoPendiente = esPago && !esStripe && !comprobanteFallidoPendiente && rastreoPendiente.length >= 8;
const comprobanteConIdentificadorPendiente = claveEnDocumentoPendiente ||
  (esPago && !esStripe && !comprobanteFallidoPendiente && folioOperacionPendiente !== '' && Number(d.monto_pago) > 0);
// Pago con tarjeta o wallet (Clip, Mercado Pago Wallet, terminal): no existe clave de
// rastreo que pedir. Se registra y lo revisa el equipo, sin solicitar datos al cliente.
// El medio de pago se lee TAMBIÃ‰N del texto visible del documento: un comprobante de
// Mercado Pago Wallet puede llegar clasificado como "transferencia" y aun así no tiene
// clave SPEI, por lo que nunca se le pide al cliente.
const textoDocumentoPendiente = [
  d.concepto_pago, d.banco_receptor, d.banco_emisor, d.nombre_beneficiario, d.nombre_ordenante,
  d.motivo_clasificacion, ...(Array.isArray(d.senales_pago) ? d.senales_pago : [])
].join(' ');
const sinAcentosPendiente = (v) => String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const tipoPagoSinSpeiPendiente = /(?:tarjeta|clip|wallet|mercado\s*pago|terminal|point)/.test(
  sinAcentosPendiente(String(d.tipo_imagen_pago ?? '') + ' ' + textoDocumentoPendiente)
);
const mencionaNegocioPendiente = /inside\s*spa|insidespa|clip\.mx|mercado\s*pago/i.test(
  textoDocumentoPendiente
);
const pagoSinClaveRastreoPendiente = esPago && !esStripe && tipoPagoSinSpeiPendiente && mencionaNegocioPendiente &&
  Number(d.monto_pago) > 0 &&
  !/fallid|rechaz|cancelad|devuelt|no realiz|no complet/.test(String(d.estado_pago_visible ?? '').toLowerCase() + ' ' + sinAcentosPendiente(d.tipo_imagen_pago));
// Destino visible distinto al nuestro: no se le pide la clave de rastreo al cliente y el
// comprobante queda para revisión de una persona del equipo (no se da por corroborado).
const destinoVisiblePendiente = String(d.cuenta_beneficiaria_visible ?? d.cuenta_beneficiaria ?? '').trim();
const destinoNoCoincidePendiente = !pagoBBVA && !aprobacionManualPorFolioPendiente &&
  destinoDigPendiente.length >= 4 && !destinoEsNuestroPendiente;
const revisionManual = pagoBBVA || aprobacionManualPorFolioPendiente || pagoSinClaveRastreoPendiente || comprobanteConIdentificadorPendiente;
const parte1 = revisionManual
  ? (claveEnDocumentoPendiente
    ? '¡Gracias por compartir tu comprobante! Ya lo tenemos en validación. ðŸŒ¿'
    : aprobacionManualPorFolioPendiente
