function detectarNumeroPersonas(mensaje, estadoActual) {
  const texto = normalizarTexto(mensaje);
  const faltantesEstado = Array.isArray(estadoActual && estadoActual.faltantes) ? estadoActual.faltantes : [];
  const personasEstado = Number(estadoActual && estadoActual.numero_personas);
  const esperandoPersonas = faltantesEstado.includes('numero_personas') ||
    !(Number.isInteger(personasEstado) && personasEstado > 0) ||
    String(estadoActual && estadoActual.ultimo_campo || '') === 'numero_personas';
  // Un "2" o "2!" suelto responde la pregunta del número de personas. Nunca es una fecha.
  const soloNumero = texto.match(/^(\d{1,2})$/);
  if (soloNumero) {
    const valor = Number(soloNumero[1]);
    if (valor >= 1 && valor <= 20 && esperandoPersonas) return valor;
  }
  // La cantidad dictada por el cliente siempre manda: se evalúa más abajo,
  // después de los números explícitos ("3 personas"), nunca antes.
  const palabras = {
    una: 1, uno: 1, un: 1, dos: 2, tres: 3, cuatro: 4, cinco: 5,
    seis: 6, siete: 7, ocho: 8, nueve: 9, diez: 10, once: 11,
    doce: 12, trece: 13, catorce: 14, quince: 15, dieciseis: 16,
    diecisiete: 17, dieciocho: 18, diecinueve: 19, veinte: 20,
  };
  const numero = texto.match(/\b(\d{1,2})\s*(?:personas?|pax)\b/);
  if (numero) {
    const valor = Number(numero[1]);
    if (Number.isInteger(valor) && valor > 0) return valor;
  }
  const palabra = texto.match(/\b(una|uno|un|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez|once|doce|trece|catorce|quince|dieciseis|diecisiete|dieciocho|diecinueve|veinte)\s*(?:personas?|pax)\b/);
  if (palabra) return palabras[palabra[1]];
  const somos = texto.match(/\b(?:somos|seremos|vamos|iriamos|van|son|para)\s+(una|uno|un|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez|once|doce|trece|catorce|quince|dieciseis|diecisiete|dieciocho|diecinueve|veinte)\b/);
  if (somos) return palabras[somos[1]];
  // "spa day con mi hermana" son dos personas. No se aplica a plurales ni a
  // varias personas mencionadas ("con mi hermana y mi mamá" son tres).
  const acompanantes = texto.match(/\b(?:con|y)\s+mi\s+(?:hermana|hermano|mama|papa|madre|padre|esposa|esposo|marido|novia|novio|pareja|amiga|amigo)\b/g) || [];
  const acompanantesPlurales = /\b(?:hermanas|hermanos|amigas|amigos|primas|primos|tias|tios|comadres|invitadas|invitados)\b/.test(texto);
  if (acompanantes.length === 1 && !acompanantesPlurales && esperandoPersonas) return 2;
  const contextoCantidad =
    estadoActual?.ultimo_campo === 'numero_personas' ||
    ['RECOPILANDO_DATOS', 'VALIDANDO_DISPONIBILIDAD', 'ELIGIENDO_ALTERNATIVA'].includes(String(estadoActual?.estado ?? '')) || /\b(?:full|budha|buda|premium|temazcal)\b/.test(texto);
  if (contextoCantidad && /\bpareja\b/.test(texto)) return 2;
  if (contextoCantidad && /\bindividual\b/.test(texto)) return 1;
  return null;
}

function mensajeEsSoloSucursal(mensaje) {
  const texto = normalizarTexto(mensaje);
  return /^(?:(?:inside spa|spa|sucursal)\s+)?(?:del\s+)?(?:valle|polanco|juarez|lomas(?: de chapultepec)?|roma(?: norte)?|24077|24079|24080|24082|24221)$/.test(texto);
