function presente(value) {
  return value !== null &&
    value !== undefined &&
    !(typeof value === 'string' && /^(?:\s*|null|undefined|n\/a)$/i.test(value.trim()));
}

function limpiar(value) {
  return typeof value === 'string' ? value.trim() : value;
}

function normalizarTexto(value) {
  return String(value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[¡!¿?,.;:]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

function fechaLocalISO(instante = new Date()) {
  const partes = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Mexico_City',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(instante);

  const valores = Object.fromEntries(
    partes
      .filter((parte) => parte.type !== 'literal')
      .map((parte) => [parte.type, parte.value])
  );

  return `${valores.year}-${valores.month}-${valores.day}`;
}

function sumarDiasISO(fechaISO, dias) {
  const [year, month, day] = fechaISO.split('-').map(Number);
  const fecha = new Date(Date.UTC(year, month - 1, day + dias, 12, 0, 0));
  return fecha.toISOString().slice(0, 10);
}

function resolverFechaMensaje(mensaje, estadoActual, fechaExtraida, opciones) {
  opciones = opciones || {};
  const texto = normalizarTexto(mensaje);
  const hoy = fechaLocalISO();
  const dias = { domingo: 0, lunes: 1, martes: 2, miercoles: 3, jueves: 4, viernes: 5, sabado: 6 };
  const meses = { enero: 1, febrero: 2, marzo: 3, abril: 4, mayo: 5, junio: 6, julio: 7, agosto: 8, septiembre: 9, setiembre: 9, octubre: 10, noviembre: 11, diciembre: 12 };
  const fallar = motivo => ({ fecha: null, motivo, reconocida: true });
  function construir(y, m, d) {
    if (!Number.isInteger(y) || y < 2000 || y > 2100 || m < 1 || m > 12 || d < 1 || d > 31) return null;
    const dt = new Date(Date.UTC(y, m - 1, d, 12));
    return dt.getUTCFullYear() === y && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d
      ? dt.toISOString().slice(0, 10) : null;
  }
  const diaNombrado = texto.match(/\b(domingo|lunes|martes|miercoles|jueves|viernes|sabado)\b/)?.[1];
  function validar(fecha) {
    if (!fecha) return fallar('FECHA_CALENDARIO_INVALIDA');
    if (fecha < hoy) return fallar('FECHA_PASADA');
    if (diaNombrado && new Date(fecha + 'T12:00:00Z').getUTCDay() !== dias[diaNombrado]) return fallar('DIA_SEMANA_NO_COINCIDE');
    return { fecha, motivo: null, reconocida: true };
  }
  const iso = texto.match(/\b(20\d{2})-(\d{2})-(\d{2})\b/);
  if (iso) return validar(construir(+iso[1], +iso[2], +iso[3]));
  const fechaTexto = texto.match(/\b(\d{1,2})\s+(?:de\s+)?(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre)(?:\s+(?:de[l]?\s+)?(20\d{2}))?\b/);
  if (fechaTexto) {
    const anio = fechaTexto[3] ? +fechaTexto[3] : +hoy.slice(0, 4);
    return validar(construir(anio, meses[fechaTexto[2]], +fechaTexto[1]));
  }
  const numerica = texto.match(/\b(\d{1,2})[\/\-](\d{1,2})(?:[\/\-](20\d{2}))?\b/);
  if (numerica) return validar(construir(numerica[3] ? +numerica[3] : +hoy.slice(0, 4), +numerica[2], +numerica[1]));

  // Un número de día nunca se ignora para elegir simplemente el próximo domingo.
  const diaConNumero = texto.match(/\b(domingo|lunes|martes|miercoles|jueves|viernes|sabado)\s+(?:el\s+)?(?:dia\s+)?(\d{1,2})\b/);
  // Un número suelto es un día SOLO si la fecha es el dato que realmente falta.
  // Después de "¿me confirmas el número de personas?", un "2" es la cantidad, no el día 2.
  const faltantesFecha = Array.isArray(estadoActual && estadoActual.faltantes) ? estadoActual.faltantes : [];
  const diaSolo = (opciones.permitirDiaSuelto === true && faltantesFecha.includes('fecha'))
    ? texto.match(/^(?:(?:para\s+)?el\s+)?(?:dia\s+)?(\d{1,2})(?:\s+(?:por\s*favor|porfa))?$/)
    : null;
  if (diaConNumero || (diaSolo && estadoActual.ultimo_campo === 'fecha')) {
    const numero = +(diaConNumero ? diaConNumero[2] : diaSolo[1]);
    const previa = String(estadoActual.fecha ?? '');
    const referencia = /^\d{4}-\d{2}-\d{2}$/.test(previa) && previa >= hoy ? previa : hoy;
    let y = +referencia.slice(0, 4), m = +referencia.slice(5, 7);
    let fecha = construir(y, m, numero);
    if (fecha && fecha < hoy && referencia === hoy) {
      m++; if (m === 13) { m = 1; y++; }
      fecha = construir(y, m, numero);
    }
    return validar(fecha);
  }
  if (/\bpasado manana\b/.test(texto)) return validar(sumarDiasISO(hoy, 2));
  if (/\bmanana\b/.test(texto) && !/\b(?:por|en|de) la manana\b/.test(texto)) return validar(sumarDiasISO(hoy, 1));
  if (/\bhoy\b/.test(texto)) return validar(hoy);
  if (diaNombrado) {
    if (/\b(ayer|pasado|anterior)\b/.test(texto)) return fallar('FECHA_PASADA');
    const actual = new Date(hoy + 'T12:00:00Z').getUTCDay();
    let delta = (dias[diaNombrado] - actual + 7) % 7;
    if (delta === 0) delta = 7;
    return validar(sumarDiasISO(hoy, delta));
  }
  if (presente(fechaExtraida)) {
    const f = String(fechaExtraida).match(/^(\d{4})-(\d{2})-(\d{2})$/);
    return f ? validar(construir(+f[1], +f[2], +f[3])) : fallar('FECHA_NO_NORMALIZADA');
  }
  return { fecha: null, motivo: null, reconocida: false };
}

