  (/^(si|si por favor|si esa|si esa experiencia|si me interesa|claro|esa experiencia|me interesa|de acuerdo|acepto|perfecto|ok|va)$/.test(textoServicioLiteral) || /^(?:si|claro|ok|va|de acuerdo|perfecto)(?:\s+(?:a que hora(?:s)?(?: se puede| puede ser| hay| tienen| tienes| esta disponible)?|que horarios?(?: hay| tienen| tienes| estan disponibles)?|tienen disponibilidad|tienes disponibilidad|quiero ver horarios|quiero ver disponibilidad))?$/.test(textoServicioLiteral));
if (aceptaUnicaPropuesta) {
  bookingState.servicio = spaCanonical('Premium Day Spa', Number(bookingState.numero_personas));
  bookingState.servicio_confirmado = bookingState.servicio;
  bookingState.servicio_usuario = 'Premium Day Spa (aceptó la propuesta explícita)';
}
const candidatoComercial = String(bookingState.servicio || '');
const familiaComercial = spaFamily(candidatoComercial, Number(bookingState.numero_personas || 0));
const nombreSinModalidad = spaNorm(candidatoComercial).replace(/ (individual|pareja|tribu)$/, '');
const genericoRelajante = /^(?:masaje(?:s)?(?: relajante(?:s)?)?(?: sin jacuzzi)?|relajante)$/.test(nombreSinModalidad);
const genericoFacial = /^(?:facial|facial limpiador hidratante|limpiador hidratante|facial hidratante)$/.test(nombreSinModalidad);
const pideRelajanteSinVariante = /\bmasajes? (?:relajantes?|sin jacuzzi|para dos|para 2|en pareja)\b/.test(textoServicioLiteral) && !/\b(50|80|120)\b/.test(textoServicioLiteral);
const mencionaPromocionLiteral = /\b(premium|full day spa|fulldayspa|budha|buddha|temazcal bliss|elephant glow)\b/.test(textoServicioLiteral);
const anteriorEraExperiencia = !!spaFamily(current.servicio, Number(current.numero_personas || 0));
const pideSoloMasaje = /\b(solo|solamente|unicamente) (?:el |un )?masaje\b/.test(textoServicioLiteral);
const rechazaPremium = current.servicio_sugerido === 'premium_day_spa' && (/\bno(?: quiero| deseo| me interesa)? (?:el )?premium\b/.test(textoServicioLiteral) || /^(no|no gracias)$/.test(textoServicioLiteral));
const noElegioPromocion = pideRelajanteSinVariante && !mencionaPromocionLiteral && (!anteriorEraExperiencia || pideSoloMasaje || /\bsin jacuzzi\b/.test(textoServicioLiteral));
const pideFacialSinVariante = /\bfacial (?:limpiador hidratante|hidratante)\b/.test(textoServicioLiteral) && !mencionaPromocionLiteral && (!anteriorEraExperiencia || /\b(solo|unicamente|prefiero|cambiar)\b/.test(textoServicioLiteral));
const casoFacialSinIdentidad = genericoFacial || pideFacialSinVariante;

// Evita que el extractor amplíe Premium a la variante & Facial por mencionar
// la mascarilla incluida. La variante solo procede si se pide por su nombre.
if (familiaComercial?.root.startsWith('premium_day_spa') && /\bpremium\b/.test(textoServicioLiteral)) {
  const pideVarianteLiteral = /\bpremium(?: day(?: spa)?)?\s+(?:y\s+)?facial\b/.test(textoServicioLiteral);
  const raizPremium = pideVarianteLiteral ? 'premium_day_spa_facial' : 'premium_day_spa';
  if (familiaComercial.root !== raizPremium) {
    bookingState.servicio = raizPremium + (familiaComercial.mod ? '_' + familiaComercial.mod : '');
    bookingState.servicio_confirmado = bookingState.servicio;
    bookingState.servicio_usuario = mensajeServicioLiteral;
  }
}

const requiereAclararServicio = genericoRelajante || casoFacialSinIdentidad || noElegioPromocion || rechazaPremium;
if (requiereAclararServicio) {
  bookingState.servicio_usuario = presente(slots.servicio) || noElegioPromocion
    ? mensajeServicioLiteral : (current.servicio_usuario || candidatoComercial.replace(/_/g, ' '));
  bookingState.servicio = null;
  bookingState.servicio_confirmado = null;
  bookingState.servicio_requiere_aclaracion = true;
  bookingState.motivo_servicio = rechazaPremium ? 'OTRO_SERVICIO_PENDIENTE' : casoFacialSinIdentidad ? 'FACIAL_SIN_IDENTIDAD_EXACTA' : 'MASAJE_SIN_EXPERIENCIA_ELEGIDA';
  bookingState.servicio_sugerido = casoFacialSinIdentidad || rechazaPremium ? null : 'premium_day_spa';
  bookingState.horario_validado = false;
  bookingState.plantilla_enviada = false;
} else if (presente(bookingState.servicio) && current.servicio_requiere_aclaracion) {
  bookingState.servicio_requiere_aclaracion = false;
  bookingState.motivo_servicio = null;
  bookingState.servicio_sugerido = null;
  if (presente(slots.servicio) && !aceptaUnicaPropuesta) bookingState.servicio_usuario = mensajeServicioLiteral;
}

// La modalidad ya determina el número de personas: pareja son dos e individual una.
// Nunca se vuelve a preguntar un dato que la modalidad del servicio ya fija.
if (presente(bookingState.servicio) && !presente(bookingState.numero_personas)) {
  const modalidadServicio = String(bookingState.servicio).match(/_(individual|pareja|tribu)$/);
  if (modalidadServicio && modalidadServicio[1] === 'individual') bookingState.numero_personas = 1;
  else if (modalidadServicio && modalidadServicio[1] === 'pareja') bookingState.numero_personas = 2;
}


const multi=prepared.multi||{};
// La sede exclusiva es un dato conocido del servicio de esta solicitud, aunque el extractor no la emita.
// Resolver ya separó la solicitud nueva de cualquier borrador anterior.
if (!multi.infoOnly && !multi.blocked) {
  const familiaSede=String(bookingState.servicio_confirmado || bookingState.servicio || '').replace(/_(individual|pareja|tribu)$/,'');
  const sedeExclusiva={elephant_glow:'24079',temazcal_bliss:'24080'}[familiaSede];
  if (sedeExclusiva) {
    const sedeActual=detectarSucursalCanonica(String(bookingState.sucursal || ''));
    if (!sedeActual && !bookingState.reserva_draft_id) bookingState.sucursal=sedeExclusiva;
    else if (sedeActual!==sedeExclusiva) {
      multi.blocked=true; multi.allowAvailability=false; multi.allowSave=false;
      multi.reason='SUCURSAL_INCOMPATIBLE_CON_EXPERIENCIA_EXCLUSIVA';
    }
  }
}
// --- ANTI-BUCLE: una afirmacion pura acepta lo que Sara acaba de proponer ---
// Regla de negocio: si el cliente dice "si" a la pregunta anterior de Sara, ese "si"
// responde ESA pregunta. Nunca se convierte en una pregunta nueva ni en un bucle.
const textoAfirmacion = String(prepared.Respuesta_definitiva || '').normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '').toLowerCase()
  .replace(/[\u00bf?\u00a1!.,:;]/g, '').replace(/\s+/g, ' ').trim();
const AFIRMACION_PURA = /^(?:si+|sip|sii+|claro|claro que si|ok|okay|va|vale|correcto|es correcto|asi es|exacto|perfecto|de acuerdo|confirmo|si confirmo|si por favor|por favor si|afirmativo|yes)(?: por favor)?$/.test(textoAfirmacion);
if (AFIRMACION_PURA) {
  // 1) Acepta la experiencia que Sara acaba de proponer (no se inventa otra).
  if (bookingState.servicio_requiere_aclaracion === true) {
    const propuesta = bookingState.servicio_sugerido || (multi.topic && multi.topic.servicio) || null;
    if (propuesta) {
      bookingState.servicio = spaCanonical(propuesta, Number(bookingState.numero_personas || 0));
      bookingState.servicio_confirmado = bookingState.servicio;
      bookingState.servicio_requiere_aclaracion = false;
      bookingState.motivo_servicio = null;
      bookingState.servicio_sugerido = null;
    }
  }
  // 2) Si el resolver dudo de la intencion solo porque llego un "si" suelto sobre una
  //    experiencia nueva, ese "si" la acepta: se desbloquea la consulta.
  if (multi.blocked === true && multi.reason === 'ACLARAR_INTENCION_SOBRE_NUEVA_EXPERIENCIA') {
    multi.blocked = false; multi.reason = null; multi.allowAvailability = true;
    const temaServicio = (multi.topic && multi.topic.servicio) || null;
    if (temaServicio && !presente(bookingState.servicio)) {
      bookingState.servicio = spaCanonical(temaServicio, Number(bookingState.numero_personas || 0));
      bookingState.servicio_confirmado = bookingState.servicio;
    }
  }
  // 3) El "si" responde el dato que Sara acaba de preguntar: no se vuelve a preguntar.
  if (String(bookingState.ultimo_campo || '') === 'numero_personas' && !presente(bookingState.numero_personas)) {
    const modalidadAfirmada = String(bookingState.servicio || bookingState.servicio_confirmado || '').match(/_(individual|pareja|tribu)$/);
    if (modalidadAfirmada) bookingState.numero_personas = modalidadAfirmada[1] === 'individual' ? 1 : modalidadAfirmada[1] === 'pareja' ? 2 : 3;
  }
  bookingState.ultimo_campo = null;
}

if(multi.infoOnly || multi.blocked) {
  for(const k of ['servicio','servicio_confirmado','servicio_usuario','sucursal','sucursal_solicitada','fecha','horario','numero_personas','reserva_draft_id','link_pago','borrador_guardado','plantilla_enviada','horario_validado','opciones_verificadas','modo_busqueda','hora_minima']) bookingState[k]=current[k]??null;
  intencionEfectiva=multi.modify?'transferencia':'informacion';
}
if(multi.contextualAvailability && !multi.blocked && !multi.infoOnly) intencionEfectiva='respuesta_reserva';
bookingState.solicitud_id=multi.activeId;
bookingState.solicitud_activa_id=multi.activeId;
bookingState.solicitudes=multi.requests||{};
bookingState.tema_consulta=multi.topic||{};
bookingState.multi_bloqueado=!!multi.blocked;
bookingState.motivo_multi=multi.reason||null;
