if(multi.newRequest || multi.infoOnly) bookingState.horario_validado=false;


// La aceptación se resuelve contra las opciones verificadas, sin inferir datos desde la memoria del modelo.
const decisionSeleccion=preguntaPorHora ? null : (multi.selectionDecision || null);
if(decisionSeleccion && !multi.blocked) {
  intencionEfectiva='respuesta_reserva';
  bookingState.intencion_prereserva=decisionSeleccion.tipo==='PRERESERVA_ACEPTADA';
  if(decisionSeleccion.opcion) {
    const o=decisionSeleccion.opcion;
    const exacta=(bookingState.opciones_verificadas || []).some(v=>String(v.servicio)===String(o.servicio) && String(v.sucursal)===String(o.sucursal) && String(v.fecha)===String(o.fecha) && String(v.horario || v.hora_inicio)===String(o.horario));
    if(!exacta) throw new Error('OPCION_SELECCIONADA_NO_VERIFICADA');
