}

const faltantes = fields.filter((field) => !presente(bookingState[field]));
const camposOperativos = ['servicio','sucursal','fecha','numero_personas'];
if (presente(bookingState.sucursal)) bookingState.sucursal = detectarSucursalCanonica(String(bookingState.sucursal));
if (!Number.isInteger(bookingState.numero_personas) || bookingState.numero_personas < 1) bookingState.numero_personas = null;
const faltantes_operativos = camposOperativos.filter((field) => !presente(bookingState[field]));
if (bookingState.fecha_requiere_aclaracion && !faltantes_operativos.includes('fecha')) faltantes_operativos.push('fecha');
const datos_operativos_completos = faltantes_operativos.length === 0;
// La herramienta solo recibe consultas completas de la solicitud activa.
bookingState.permitir_disponibilidad = !!multi.allowAvailability && !multi.blocked && datos_operativos_completos && !bookingState.servicio_requiere_aclaracion;

const datosCompletos = faltantes.length === 0;
const intencionReserva = ['iniciar_reserva', 'respuesta_reserva'].includes(intencionEfectiva);
const seleccionoHoraExplicita =
  esperandoConfirmacion &&
  horaExplicita &&
  presente(slots.horario);

if (pidioVerAlternativas && datos_operativos_completos) {
  bookingState.estado = 'VALIDANDO_DISPONIBILIDAD';
  bookingState.ultimo_campo = null;
  bookingState.solicitar_alternativas = true;
} else if (
  esperandoConfirmacion &&
  presente(bookingState.horario) &&
  (
    (esperandoConfirmacionExacta && confirmaHorario) ||
    seleccionoHoraExplicita
  )
) {
  bookingState.estado = 'DISPONIBILIDAD_CONFIRMADA';
  bookingState.ultimo_campo = null;
} else if (intencionReserva) {
  bookingState.estado = datos_operativos_completos
    ? 'VALIDANDO_DISPONIBILIDAD'
    : 'RECOPILANDO_DATOS';
  bookingState.ultimo_campo = faltantes_operativos[0] ?? (datos_operativos_completos ? null : faltantes[0]) ?? null;
} else if (!esperandoConfirmacion && bookingState.estado === 'RECOPILANDO_DATOS') {
  bookingState.ultimo_campo = faltantes[0] ?? bookingState.ultimo_campo ?? null;
}

// Consultar otro horario no registra ni confirma la selección anterior.
if (preguntaPorHora && multi.allowAvailability && !multi.blocked && !multi.infoOnly
    && !current.reserva_draft_id && !current.borrador_guardado && !current.reserva_confirmada) {
  intencionEfectiva = 'respuesta_reserva';
  bookingState.horario = horaConsultaExplicita;
  bookingState.modo_busqueda = 'hora_preferida';
  bookingState.hora_minima = null;
  bookingState.horario_validado = false;
  bookingState.intencion_prereserva = false;
  bookingState.permitir_guardar = false;
  bookingState.interaccion_pendiente = null;
  bookingState.ultima_accion_bot = null;
  bookingState.ultimo_campo = null;
  bookingState.estado = 'VALIDANDO_DISPONIBILIDAD';
}
bookingState.updated_at = new Date().toISOString();

return [{
  json: {
    consulta_hora_explicita: preguntaPorHora,
    solo_consulta_disponibilidad: (preguntaPorHora || multi.contextualAvailability || /disponibilidad|ver horarios|horarios disponibles/i.test(prepared.Respuesta_definitiva||'')) && !multi.allowSave,
    decision_seleccion: decisionSeleccion,
    responder_seleccion_contextual: Boolean(decisionSeleccion && (decisionSeleccion.tipo!=='PRERESERVA_ACEPTADA' || ['nombre','correo','telefono'].some(k=>!presente(bookingState[k])))),
    multi_informativo: !!multi.infoOnly,
