    datos_completos: datosCompletos,
    confirmacion_horario: esperandoConfirmacion && confirmaHorario,
    confirmacion_reserva_detalle: confirmacionReservaDetalle,
    pregunta_informativa_directa: preguntaInformativaDirecta,
    seleccion_servicio_sin_plantilla: seleccionoServicioSinPlantilla,
    fecha_referencia_local: hoyLocal,
    fecha_relativa_detectada: fechaRelativaFutura,
    fecha_descartada_por_pasada: fechaDescartadaPorPasada,
    normalizacion_determinista: {
