      numero_personas_detectado: personasDeterministas
    },
    booking_state: {
      ...bookingState,
      faltantes,
      datos_completos: datosCompletos
    }
  }
}];
})();

const texto=String($('contexto de reserva').first().json.Respuesta_definitiva||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const gestion=/\b(confirmo|confirmamos)\b.{0,45}\b(asistencia|cita|reserva)\b|\b(quiero|quisiera|deseo|me gustaria)\s+confirmar\s+(?:(?:mi|la|nuestra)\s+)?reserva\b|\b(consultar|verificar|confirmar|revisar)\b.{0,30}\b(mi|nuestra)\s+(cita|reserva)\b|\b(mi|nuestra)\s+(cita|reserva)\b.{0,25}\b(agendada|confirmada|sigue|esta)\b|\b(tengo|quedo)\b.{0,20}\b(cita|reserva)\b|\b(confirmo|confirmamos)\s+(mi\s+)?asistencia\b/.test(texto);
