 const fecha=String(b.fecha||'');
 const fechaValida=/^\d{4}-\d{2}-\d{2}$/.test(fecha)&&!isNaN(Date.parse(fecha+'T12:00:00Z'))&&new Date(fecha+'T12:00:00Z').toISOString().slice(0,10)===fecha&&fecha>=hoy;
 if(fechaValida&&b.motivo_fecha==='FECHA_PASADA'){
  b.fecha_requiere_aclaracion=false;b.motivo_fecha=null;d.fecha_requiere_aclaracion=false;d.motivo_fecha=null;
 }
 const faltan=[];
 const servicio=String(b.servicio_confirmado||b.servicio||'').trim();
 if(!servicio||b.servicio_requiere_aclaracion)faltan.push('servicio');
 const sucursal=String(b.sucursal||'');
 if(!['24077','24079','24080','24082','24221'].includes(sucursal))faltan.push('sucursal');
 if(!fechaValida||b.fecha_requiere_aclaracion)faltan.push('fecha');
 const personas=Number(b.numero_personas);
 if(!Number.isInteger(personas)||personas<1)faltan.push('numero_personas');
 const modo=b.modo_busqueda||'dia_completo';
 if(!['dia_completo','hora_preferida','tarde'].includes(modo))faltan.push('modo_busqueda');
 if(modo==='hora_preferida'&&!/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(String(b.horario||'')))faltan.push('horario');
 const sid=String(d.subscriber_id||'').trim(),sol=String(b.solicitud_id||'').trim();
 const multi=$('Resolver solicitud activa').first().json.multi||{};
 const autorizado=multi.allowAvailability===true&&!multi.blocked&&!multi.infoOnly&&!b.multi_bloqueado&&!d.gestion_reserva_existente&&!d.pregunta_informativa_directa&&d.intencion!=='informacion';
 b.permitir_disponibilidad=autorizado&&faltan.length===0&&!!sid&&!!sol;
 d.faltantes_operativos=faltan;d.datos_operativos_completos=faltan.length===0;
 const mensajeContrato=String(d.mensaje_cliente||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[¡!¿?,.;:]/g,' ').replace(/\s+/g,' ').trim().toLowerCase();
