// Contrato de public.booking_state.estado verificado en Supabase el 2026-09-11.
// El ciclo de la pre-reserva pertenece a estado_reserva y no a esta columna.
const ESTADOS_CONVERSACION = new Set([
  'SIN_RESERVA','RECOPILANDO_DATOS','DATOS_COMPLETOS',
  'VALIDANDO_DISPONIBILIDAD','ELIGIENDO_ALTERNATIVA',
  'DISPONIBILIDAD_CONFIRMADA','LINK_ENVIADO','TRANSFERENCIA_PENDIENTE'
]);
const ESTADOS_PRERESERVA = new Set([
  'esperando_datos','esperando_disponibilidad','esperando_pago',
  'procesando_pabau','confirmado','requiere_revision','expirado',
  'creando_retencion','pendiente_pago','cancelando_expirada',
  'expirado_sin_pago','requiere_revision_pago','cancelado'
]);
function estadoConversacion(estado, b={}) {
  const original=String(estado??'').trim();
  const mayusculas=original.toUpperCase();
  if(ESTADOS_CONVERSACION.has(mayusculas))return mayusculas;
  const e=original.toLowerCase();
  if(!e)return 'SIN_RESERVA';
  if(['esperando_pago','pendiente_pago'].includes(e))return String(b.link_pago??'').trim() ? 'LINK_ENVIADO' : 'DATOS_COMPLETOS';
  if(e==='esperando_datos')return 'RECOPILANDO_DATOS';
  if(e==='esperando_disponibilidad')return 'VALIDANDO_DISPONIBILIDAD';
  if(['procesando_pabau','creando_retencion','confirmado','cancelando_expirada'].includes(e))return 'DATOS_COMPLETOS';
  if(['expirado','expirado_sin_pago','cancelado'].includes(e))return 'SIN_RESERVA';
  // También conserva entradas desconocidas para revisión sin eludir el CHECK.
  return 'TRANSFERENCIA_PENDIENTE';
}
function normalizarEstadoConversacion(b) {
  if(!b || typeof b!=='object' || Array.isArray(b))return b;
  const original=String(b.estado??'').trim();
  const e=original.toLowerCase();
  if(ESTADOS_PRERESERVA.has(e))b.estado_reserva=e;
  else if(original && !ESTADOS_CONVERSACION.has(original.toUpperCase()))b.estado_origen_no_reconocido=original;
  b.estado=estadoConversacion(original,b);
  return b;
}

const finalizarOriginal=()=>{
const d = $input.first().json || {};
const fusion = $('Fusionar estado de reserva1').first().json || {};
const booking = { ...(d.booking_state_actualizado || fusion.booking_state || {}) };

function extraerTexto(valor, profundidad = 0) {
  if (profundidad > 5 || valor === undefined || valor === null) return '';
  if (typeof valor === 'string') return valor;
  if (typeof valor === 'number' || typeof valor === 'boolean') return String(valor);
  if (Array.isArray(valor)) {
    return valor.map((item) => extraerTexto(item, profundidad + 1)).filter(Boolean).join('\n');
  }
  if (typeof valor === 'object') {
    const clavesPreferidas = ['field_value', 'content', 'text', 'output', 'message', 'mensaje', 'response', 'data'];
    const partes = [];
    for (const clave of clavesPreferidas) {
      if (Object.prototype.hasOwnProperty.call(valor, clave)) {
        const parte = extraerTexto(valor[clave], profundidad + 1);
        if (parte) partes.push(parte);
      }
    }
    return partes.join('\n');
  }
  return '';
}

function normalizarHora(valor) {
  const texto = String(valor ?? '').trim().toLowerCase();
  const match = texto.match(/^(\d{1,2}):(\d{2})/);
  if (!match) return null;
  const h = Number(match[1]);
  const m = Number(match[2]);
  if (h > 23 || m > 59) return null;
  return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
}

