const valorPrimerMensaje = contexto.es_primer_mensaje;
const indicadorPrimerMensaje =
  valorPrimerMensaje === true ||
  ['true', '1'].includes(String(valorPrimerMensaje ?? '').toLowerCase());
const hayConversacionPrevia = Boolean(
  bookingPrevio.ultima_accion_bot ||
  bookingPrevio.updated_at ||
  bookingPrevio.plantilla_enviada
);
const esPrimerMensaje = indicadorPrimerMensaje && !hayConversacionPrevia;

function quitarPresentacionRepetida(valor) {
  const contenido = extraerTexto(valor).trim();
  if (!contenido || esPrimerMensaje) return contenido;

  return contenido
    .replace(
      /^\s*¡?hola[!,.\s]*soy\s+sara,?\s*tu\s+asesora(?:\s+virtual)?\s+de\s+inside\s+spa\s*ðŸŒ¿?âœ¨?\s*/i,
