  /experiencias|promociones/.test(normalizado);

const ofrecioBuscarAlternativas =
  /quieres que te proponga[^.?!]*horarios|quieres que revise[^.?!]*horarios|quieres que busque[^.?!]*horarios/.test(normalizado);

