const snapshot = b => Object.fromEntries(requestFields.filter(k=>b[k]!==undefined).map(k=>[k,clone(b[k])]));
const emptyRequest = id => ({interaccion_pendiente:null,intencion_prereserva:false,solicitud_id:id,servicio:null,servicio_confirmado:null,servicio_usuario:null,sucursal:null,sucursal_solicitada:null,fecha:null,horario:null,numero_personas:null,estado:'SIN_RESERVA',ultimo_campo:null,plantilla_enviada:false,ultima_accion_bot:null,link_pago:null,reserva_draft_id:null,borrador_guardado:false,horario_validado:false,disponibilidad_consultada:false,modo_busqueda:'dia_completo',hora_minima:null,opciones_verificadas:[],pago_previo_declarado:false,paquete_previamente_comprado:false,servicio_requiere_aclaracion:false,servicio_sugerido:null,motivo_servicio:null,fecha_requiere_aclaracion:false,motivo_fecha:null});
function extractionOf(v, depth=0) {
  if(depth>8 || v==null)return null;
