    } catch {
      // MIME, nombre, extensión y pista segura de URL quedan como respaldo.
    }
  }

  const esPdf =
    firmaAscii.startsWith('%PDF-') ||
    mimeType === 'application/pdf' ||
    extension === 'pdf' ||
    fileName.endsWith('.pdf') ||
    hint === 'pdf';

  const esImagen = !esPdf && (
    firmaHex.startsWith('ffd8ff') ||
    firmaHex.startsWith('89504e470d0a1a0a') ||
    firmaAscii.startsWith('GIF8') ||
    (firmaAscii.startsWith('RIFF') && firmaAscii.includes('WEBP')) ||
    mimeType.startsWith('image/') ||
    ['png', 'jpg', 'jpeg', 'webp', 'gif', 'heic', 'heif'].includes(extension) ||
    /\.(?:png|jpe?g|webp|gif|heic|heif)$/.test(fileName) ||
    hint === 'imagen'
  );

  const extensionesAudioOpenAI = [
    'flac', 'mp3', 'mp4', 'mpeg', 'mpga', 'm4a', 'ogg', 'wav', 'webm',
  ];
  const firmaOgg = firmaAscii.startsWith('OggS');
  const firmaWav = firmaAscii.startsWith('RIFF') && firmaAscii.includes('WAVE');
  const firmaFlac = firmaAscii.startsWith('fLaC');
  const firmaMp3 =
    firmaAscii.startsWith('ID3') ||
    /^(fffb|fff3|fff2)/.test(firmaHex);
  const firmaM4a = firmaAscii.slice(4, 12).includes('ftypM4A');

  const esAudio = !esPdf && !esImagen && (
    mimeType.startsWith('audio/') ||
    extensionesAudioOpenAI.includes(extension) ||
    new RegExp('\\.(?:' + extensionesAudioOpenAI.join('|') + ')$').test(fileName) ||
    firmaOgg ||
    firmaWav ||
    firmaFlac ||
    firmaMp3 ||
    firmaM4a ||
    hint === 'audio'
  );

  let formatoAudio = '';
  if (esAudio) {
    if (firmaOgg || mimeType.includes('ogg')) formatoAudio = 'ogg';
    else if (firmaWav || mimeType.includes('wav')) formatoAudio = 'wav';
    else if (firmaFlac || mimeType.includes('flac')) formatoAudio = 'flac';
    else if (firmaMp3 || mimeType.includes('mpeg')) formatoAudio = 'mp3';
    else if (firmaM4a || mimeType.includes('mp4')) formatoAudio = 'm4a';
    else if (mimeType.includes('webm')) formatoAudio = 'webm';
    else if (extensionesAudioOpenAI.includes(extension)) formatoAudio = extension;
    else formatoAudio = 'ogg';
  }

  if (esAudio && propiedad) {
    const nombreValido = new RegExp('\\.(?:' + extensionesAudioOpenAI.join('|') + ')$', 'i').test(
      String(archivo.fileName ?? '')
    );
