        mpeg: 'audio/mpeg', mpga: 'audio/mpeg', m4a: 'audio/mp4',
        ogg: 'audio/ogg', wav: 'audio/wav', webm: 'audio/webm',
      };
      archivo.mimeType = mimes[formatoAudio] ?? 'audio/ogg';
    }
  }

  const limiteAudioBytes = 25 * 1024 * 1024;
  const audioDentroDelLimite = esAudio && archivoBytes > 0 && archivoBytes <= limiteAudioBytes;

  salida.push({
    json: {
      ...origen,
      binary_property: propiedad,
      archivo_mime_type: String(archivo.mimeType ?? mimeType).toLowerCase(),
      archivo_nombre: String(archivo.fileName ?? fileName),
      archivo_extension: String(archivo.fileExtension ?? extension),
