function recolectar(valor, acumulado = [], profundidad = 0) {
  if (profundidad > 8 || valor === null || valor === undefined) return acumulado;
  if (typeof valor === 'string') {
    const limpio = valor.trim();
    if (limpio) acumulado.push(limpio);
    return acumulado;
  }
  if (Array.isArray(valor)) {
    for (const item of valor) recolectar(item, acumulado, profundidad + 1);
    return acumulado;
  }
  if (typeof valor === 'object') {
    for (const item of Object.values(valor)) recolectar(item, acumulado, profundidad + 1);
  }
  return acumulado;
}

