  if (typeof v === 'string') { try { return buscar(JSON.parse(v.replace(/^```(?:json)?\s*|\s*```$/g, '')), n + 1); } catch { return null; } }
  if (typeof v === 'object' && !Array.isArray(v) && ('es_imagen_relacionada_pago' in v || 'es_comprobante_pago' in v)) return v;
  for (const x of Object.values(v)) { const r = buscar(x, n + 1); if (r) return r; }
  return null;
}

