}

function booleano(valor) {
  if (typeof valor === 'boolean') return valor;
  return ['1', 'true', 'si', 'sí', 'yes'].includes(String(valor ?? '').trim().toLowerCase());
}

function inicio(fila) {
  const valor = String(
