const d = $input.first().json ?? {};

const tipoStripe=String(d.tipo_imagen_pago??d.tipo??'').trim().toLowerCase();
const senalesStripe=[tipoStripe,...(Array.isArray(d.senales_pago)?d.senales_pago:[]),d.motivo_clasificacion].join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const esComprobanteStripe=d.es_comprobante_stripe===true||tipoStripe==='stripe'||/\bstripe\b|checkout\.stripe/.test(senalesStripe);
if(esComprobanteStripe){
  const id=String(d.reserva_draft_id??'').trim(), subscriber=String(d.subscriber_id??'').trim();
  const exacta=/^[1-9]\d*$/.test(id)&&!!subscriber&&d.borrador_encontrado===true;
  const identidad=[id,subscriber,String(d.numero_comprobante??d.numero_referencia??d.media_url??d.monto_pago??'sin_id')].join('|');
  let hash=2166136261;for(let i=0;i<identidad.length;i++)hash=Math.imul(hash^identidad.charCodeAt(i),16777619);
  const huella=String(d.huella_comprobante_previa??d.huella_comprobante??'').trim()||'stripe_revision|'+id+'|'+subscriber+'|'+(hash>>>0).toString(36);
  return [{json:{...d,es_imagen_relacionada_pago:true,es_comprobante_stripe:true,tipo_imagen_pago:'stripe',
    huella_comprobante:huella,huella_bancaria_calculada:huella,solicitar_bloqueo:exacta,
    consultar_banxico:false,comprobante_visual_corrobora:false,comprobante_basico_para_nota:false,
    comprobante_manual_sin_rastreo:false,registro_solo_revision:false,pago_verificado:false,
    comprobante_estado:'revision_stripe',estado_cliente_pago:'esperando_confirmacion_stripe',datos_a_solicitar:[],
    motivos_revision_pago:['COMPROBANTE_STRIPE_RECIBIDO_PENDIENTE_DE_WEBHOOK']}}];
}

const cfg = {
  clabe: '012225004875095530',
  cuenta: '0487509553',
  titular: 'Juan Ricardo Ceballos',
};

const text = v => {
  const s = String(v ?? '').trim();
  return /^(null|undefined)$/i.test(s) ? '' : s;
};

const norm = v =>
  text(v)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();

const digits = v => text(v).replace(/\D/g, '');

const sameName = (a, b) =>
  !!norm(a) &&
  norm(a).split(' ').sort().join(' ') ===
    norm(b).split(' ').sort().join(' ');

const compatibleName = (a, b) => {
  const x = norm(a).split(' ').filter(Boolean);
  const y = norm(b).split(' ').filter(Boolean);

  return (
    x.length >= 2 &&
    x.length <= y.length &&
    x.every(
      (v, i) => v === y[i] || (v.length === 1 && y[i]?.startsWith(v))
    )
  );
};

// El cliente puede pagar con su nombre CORTO de Instagram o con su nombre COMPLETO tal
// como lo pide el banco: "Adriana" (perfil) contra "Adriana Olivia Pastrana Arroyo"
// (comprobante), y también al revés. Se exige que el nombre corto sea el prefijo ordenado
// del largo y, si es una sola palabra, que tenga 4 letras o más (nunca una inicial suelta).
const nombrePagoCompatible = (a, b) => {
  const x = norm(a).split(' ').filter(Boolean);
  const y = norm(b).split(' ').filter(Boolean);
  if (!x.length || !y.length) return false;
  const corto = x.length <= y.length ? x : y;
  const largo = x.length <= y.length ? y : x;
  const esPrefijo = corto.every(
    (v, i) => v === largo[i] || (v.length === 1 && largo[i]?.startsWith(v))
  );
  return esPrefijo && (corto.length >= 2 || corto[0].length >= 4);
};

// Fecha original del comprobante.
const fechaActual = $now
  .setZone('America/Mexico_City')
  .toFormat('yyyy-MM-dd');

const fecha = text(d.fecha_pago);
const fechaValida =
  /^\d{4}-\d{2}-\d{2}$/.test(fecha) &&
  Number.isFinite(Date.parse(fecha + 'T12:00:00Z')) &&
  new Date(fecha + 'T12:00:00Z').toISOString().slice(0, 10) === fecha;

const fechaHoy = fechaValida && fecha === fechaActual;
const fechaAdmisible = fechaValida && fecha <= fechaActual;

// Banco y titular.
const banco = norm(d.banco_receptor);
const bancoOK =
  /^(cuenta )?(bbva|bbva mexico|bbva bancomer|bbva bancomer mexico|bancomer|40012|012|12)$/.test(
    banco
  );

const titular = text(d.nombre_beneficiario);
const titularOK = sameName(titular, cfg.titular);
const titularParcial =
  !!titular && compatibleName(titular, cfg.titular);
// Nombre abreviado autorizado solo para la nota pendiente.
const titularBasicoOK = titularOK || /^(juan ricardo|juan ricardo c)$/.test(norm(titular));
const titularConflicto =
  !!titular && !titularOK && !titularParcial;

// Cuenta visible: conservar únicamente los dígitos realmente mostrados.
const raw =
  text(d.cuenta_beneficiaria_visible) ||
  text(d.cuenta_beneficiaria);

const numero = digits(raw);
const tipo = norm(d.tipo_cuenta_beneficiaria);

const enmascarada =
  /[*xX⬢â—·]/.test(raw) ||
  d.cuenta_beneficiaria_enmascarada === true;

const finalVisible = /\d\s*$/.test(raw);

const esClabe =
  tipo === 'clabe' ||
  (!enmascarada && numero.length === 18);

const esCuenta =
  ['cuenta', 'numero de cuenta', 'cuenta bancaria'].includes(tipo) ||
  (!enmascarada && [10, 11].includes(numero.length));

// Si el tipo es desconocido, cotejar el sufijo contra ambos destinos.
// Una coincidencia parcial permite consultar; no confirma el abono.
const tipoDesconocido =
  !tipo || ['desconocida', 'desconocido'].includes(tipo);

const destinos = esClabe
  ? [{ tipo: 'CLABE', numero: cfg.clabe }]
  : esCuenta
    ? [{ tipo: 'CUENTA', numero: cfg.cuenta }]
    : tipoDesconocido
      ? [
          { tipo: 'CLABE', numero: cfg.clabe },
          { tipo: 'CUENTA', numero: cfg.cuenta },
        ]
      : [];

const completa =
  !enmascarada &&
  (esClabe
    ? numero.length === 18
    : esCuenta && [10, 11].includes(numero.length));

const fullOK =
  completa &&
  destinos.some(x =>
    x.tipo === 'CLABE'
      ? numero === x.numero
      : numero.replace(/^0+/, '') === x.numero.replace(/^0+/, '')
  );

// Una máscara puede corresponder a la cuenta o a la CLABE: se coteja contra ambas.
const destinosMascara = [
  { tipo: 'CLABE', numero: cfg.clabe },
  { tipo: 'CUENTA', numero: cfg.cuenta },
];

const coincidenciasParciales =
  enmascarada && finalVisible && numero.length >= 3
    ? destinosMascara.filter(
        x => numero.length < x.numero.length && x.numero.endsWith(numero)
      )
    : [];

const sufijoOK =
  coincidenciasParciales.length > 0 && numero.length >= 4;

const parcialOK =
  coincidenciasParciales.length > 0 && numero.length === 3;

// No usar un supuesto cuarto dígito extraído por OCR si solo se ven tres.
// Ejemplo: ***530 no permite afirmar que se ven "0530".
const ultimosVisibles = finalVisible ? numero : '';

const cuentaConflicto =
  destinos.length > 0 &&
  !!numero &&
  (completa || (enmascarada && finalVisible && numero.length >= 3)) &&
  !fullOK &&
  !sufijoOK &&
  !parcialOK;

const cuentaOK = fullOK || sufijoOK;

const beneficiarioOK =
  bancoOK && cuentaOK && titularOK;

const destinoCompatible =
  (bancoOK || !banco) &&
  !cuentaConflicto &&
  !titularConflicto &&
  (
    cuentaOK ||
    // Tres dígitos requieren además el titular autorizado (completo o abreviado).
    (parcialOK && titularBasicoOK)
  );

// Asociar el comprobante con la clienta y la pre-reserva.
const nombreCliente = text(d.nombre_reserva || d.nombre);
const ordenante = text(d.nombre_ordenante);
const concepto = text(d.concepto_pago);

const clienteCoincide =
  !!nombreCliente &&
  (
    sameName(ordenante, nombreCliente) ||
    nombrePagoCompatible(ordenante, nombreCliente) ||
    sameName(concepto, nombreCliente)
  );

const clienteConflicto =
  !!ordenante &&
  !!nombreCliente &&
  !sameName(ordenante, nombreCliente) &&
  !nombrePagoCompatible(ordenante, nombreCliente) &&
  !sameName(concepto, nombreCliente);

// PAGÃ“ OTRA PERSONA: el comprobante NO se descarta y al cliente NO se le pide nada más.
// Se protege igual y se deja la nota para que el equipo lo revise antes de aprobar.
const pagoDeTercero = clienteConflicto;
const notaPagoDeTercero = pagoDeTercero
  ? 'El comprobante lo pagó otra persona (' + ordenante + '); la pre-reserva está a nombre de ' +
    nombreCliente + '. Revisar antes de aprobar.'
  : '';

const exacta =
  /^[1-9]\d*$/.test(text(d.reserva_draft_id)) &&
  !!text(d.subscriber_id) &&
  d.borrador_encontrado === true;

const reconocido = d.es_imagen_relacionada_pago === true;
const esTransferencia =
  ['transferencia', 'deposito'].includes(norm(d.tipo_imagen_pago));

// Estado mostrado en el comprobante.
const estado = norm(d.estado_pago_visible);
const fallido =
  /fallid|rechaz|cancelad|devuelt|no realiz|no complet/.test(
    estado + ' ' + norm(d.tipo_imagen_pago)
  );

const pendiente =
  /pendiente|en proceso|procesando|programad|enviando|por enviar|en transito/.test(
    estado
  );

const completo =
  !!estado &&
  /exitosa|exitoso|completad|realizad|liquidad|aplicad|abonad|recibid/.test(estado) &&
  !fallido &&
  !pendiente;

const monto = Number(d.monto_pago);
const anticipo = Number(d.monto_esperado);

const montoOK =
  Number.isFinite(monto) &&
  monto > 0 &&
  Number.isFinite(anticipo) &&
  anticipo > 0 &&
  monto >= anticipo;

const moneda = text(d.moneda_pago).toUpperCase();
const monedaOK = moneda === 'MXN';
// Una moneda no legible no impide consultar al banco; una moneda distinta a MXN sí.
const monedaAdmisible = !moneda || monedaOK;

// Identificadores bancarios.
const trace = text(d.clave_rastreo).replace(/\s/g, '');
const folio = text(d.numero_comprobante);
const referencia = text(d.numero_referencia).replace(/\s/g, '');

// FOLIO DE OPERACIÃ“N: un comprobante que NO muestra el banco pero sí un folio de
// operación y nuestro destino visible (titular "Juan Ricardo C", cuenta ****9553 o
// CLABE ****5530) no requiere más datos del cliente: pasa a aprobación manual.
const folioSoloDigitos = digits(folio);
const referenciaSoloDigitos = digits(referencia);
const folioOperacion = folioSoloDigitos.length >= 4
  ? folioSoloDigitos
  : (referenciaSoloDigitos.length >= 8 ? referenciaSoloDigitos : '');
const destinoEsNuestro = (fullOK || sufijoOK || parcialOK) && !cuentaConflicto && titularBasicoOK;
const aprobacionManualPorFolio = exacta && reconocido && esTransferencia &&
  folioOperacion !== '' && destinoEsNuestro &&
  !fallido && !pendiente && fechaAdmisible && !clienteConflicto && !titularConflicto &&
  Number.isFinite(monto) && monto > 0 && (!moneda || monedaOK);

const refBanco =
  d.referencia_bancaria_identificada === true &&
  /^\d{1,7}$/.test(referencia)
    ? referencia
    : '';

// PAGO CON TARJETA O WALLET SIN CLAVE DE RASTREO (Clip, Mercado Pago Wallet, terminal):
// no existe clave de rastreo que pedir ni operación SPEI que consultar en Banxico. El
// comprobante se protege y se envía a revisión manual del equipo (correo de 4.4 + 4.3).
const textoDocumento = [
  concepto,
  ordenante,
  text(d.nombre_beneficiario),
  text(d.banco_receptor),
  text(d.motivo_clasificacion),
  ...(Array.isArray(d.senales_pago) ? d.senales_pago : []),
].join(' ');
const tipoPagoSinSpei = /(?:tarjeta|clip|wallet|mercado pago|terminal|point)/i.test(
  norm(d.tipo_imagen_pago) + ' ' + textoDocumento
);
const mencionaNegocio = /inside\s*spa|insidespa|clip\.mx|mercado\s*pago/i.test(textoDocumento);
const mencionaCliente = !!nombreCliente && [concepto, ordenante].some(
  v => !!v && (sameName(v, nombreCliente) || nombrePagoCompatible(v, nombreCliente))
);
// El emisor de una wallet no es un banco y no se exige: basta el destino corroborado
// (máscara de nuestra cuenta o CLABE), el negocio mencionado o el nombre del cliente.
// Quien paga puede ser otra persona: la discrepancia de nombre se registra para que el
// equipo la revise, no bloquea la protección.
const destinoOServicioCorrobora = destinoCompatible || mencionaNegocio || mencionaCliente;
const pagoSinClaveRastreo =
  exacta &&
  reconocido &&
  !fallido &&
  !pendiente &&
  !trace &&
  !refBanco &&
  tipoPagoSinSpei &&
  destinoOServicioCorrobora &&
  Number.isFinite(monto) &&
  monto > 0 &&
  montoOK &&
  monedaAdmisible &&
  fechaAdmisible &&
  !titularConflicto &&
  !cuentaConflicto;

const reasons = [];

if (!exacta) reasons.push('FALTA_PRERESERVA_EXACTA');
if (!reconocido) reasons.push('COMPROBANTE_NO_RECONOCIDO');
if (!esTransferencia) reasons.push('PAGO_NO_ES_TRANSFERENCIA_O_DEPOSITO');
if (pagoSinClaveRastreo) reasons.push('PAGO_CON_TARJETA_O_WALLET_SIN_RASTREO_REVISION_MANUAL');

if (!destinoCompatible) {
  reasons.push(
    cuentaConflicto
      ? 'CUENTA_BENEFICIARIA_NO_COINCIDE'
      : 'BENEFICIARIO_NO_CORROBORADO'
  );
}

if (!titularBasicoOK) reasons.push('TITULAR_INCOMPLETO_O_NO_VISIBLE');

if (!cuentaOK) {
  reasons.push(
    parcialOK
      ? 'CUENTA_PARCIAL_REQUIERE_VALIDACION_BANCARIA'
      : 'CUENTA_INCOMPLETA_O_TIPO_NO_IDENTIFICADO'
  );
}

if (clienteConflicto) reasons.push('NOMBRE_CLIENTE_NO_COINCIDE');
if (pagoDeTercero) reasons.push('PAGO_DE_TERCERO_REVISAR');

if (!fechaAdmisible) {
  reasons.push(fechaValida ? 'FECHA_PAGO_FUTURA' : 'FECHA_PAGO_NO_VALIDA');
}

if (!montoOK) reasons.push('MONTO_INSUFICIENTE_O_NO_LEGIBLE');
if (!monedaAdmisible) reasons.push('MONEDA_NO_CORROBORADA');

if (fallido) {
  reasons.push('PAGO_FALLIDO');
} else if (!completo) {
  reasons.push(
    pendiente ? 'OPERACION_EN_PROCESO' : 'ESTADO_PAGO_NO_CORROBORADO'
  );
}

// Consultar con la fecha real del comprobante, actual o anterior.
// Nunca sustituirla por hoy ni admitir fechas futuras.
const baseConsulta =
  exacta &&
  reconocido &&
  esTransferencia &&
  destinoCompatible &&
  fechaAdmisible &&
  montoOK &&
  monedaAdmisible &&
  !clienteConflicto &&
  !fallido;

// Una pre-reserva LIBERADA por falta de pago ya no tiene citas en Pabau: el pago tardío
// no se consulta en Banxico porque no se puede finalizar sin citas. Se registra, se protege
// y lo aprueba el asesor; al aprobarlo, el flujo 4.5 recrea la cita con el mismo horario.
const liberadaSinCitas = String(d.estado_reserva ?? '') === 'expirado_sin_pago'
  || Boolean(String(d.retencion_cancelada_at ?? '').trim())
  || d.pabau_reservado === false;
if (liberadaSinCitas) reasons.push('PRE_RESERVA_LIBERADA_REQUIERE_APROBACION');
// No exigir estado visual de éxito para consultar al banco.
const consultar =
  !liberadaSinCitas &&
  baseConsulta &&
  !!text(d.banco_emisor) &&
  !!(trace || refBanco);

if (!trace && !refBanco) {
  reasons.push('SIN_RASTREO_NI_REFERENCIA_BANCARIA');
}

if ((trace || refBanco) && !text(d.banco_emisor)) {
  reasons.push('FALTA_INSTITUCION_EMISORA');
}

// Corroboración visual no equivale a pago verificado por banco.
const visual =
  baseConsulta &&
  beneficiarioOK &&
  completo &&
  !trace &&
  !refBanco &&
  !!folio;

if (!trace && !refBanco && !folio && !folioOperacion) {
  reasons.push('FALTA_FOLIO_PARA_IDENTIFICAR_COMPROBANTE');
}

const identidad = trace
  ? 'rastreo:' + norm(d.banco_emisor) + ':' + trace
  : refBanco
    ? 'referencia:' + norm(d.banco_emisor) + ':' + refBanco
    : (folio || folioOperacion)
      ? 'folio:' + (folio || folioOperacion)
      : '';

let huella =
  identidad && fechaValida
    ? cfg.clabe + '|' + fecha + '|' + identidad
    : '';

// Corroboración mínima exclusivamente para una nota pendiente, nunca para confirmar pago.
const notaBasica = exacta && reconocido && esTransferencia && titularBasicoOK &&
  (fullOK || sufijoOK || parcialOK) && !cuentaConflicto &&
  (!banco || bancoOK) && !clienteConflicto && !fallido &&
  Number.isFinite(monto) && monto>0 && (!moneda || monedaOK) &&
  fechaValida && fecha<=fechaActual && completo;
// Excepción para revisión manual, NO equivale a estado exitoso ni pago confirmado.
// Un folio visible identifica el comprobante; nunca se transforma en rastreo SPEI.
const comprobanteManualSinRastreo = exacta && reconocido && esTransferencia &&
  titularBasicoOK && (fullOK || sufijoOK || parcialOK) && !cuentaConflicto &&
  (bancoOK || aprobacionManualPorFolio) && !fallido && !pendiente && fechaAdmisible &&
  Number.isFinite(monto) && monto > 0 && (!moneda || monedaOK) &&
  !!(folio || folioOperacion) && !trace && !refBanco;
// Identificador interno de revisión cuando el documento no trae rastreo/folio/fecha.
// No es un identificador bancario ni permite confirmar la transferencia.
if (!huella && notaBasica) {
  huella = ['revision_visual',cfg.clabe,fechaValida?fecha:'sin_fecha',numero,
    String(monto),norm(titular)].join('|');
}

// Proteger mientras se revisa, aunque falten datos para confirmar.
// Esto solicita detener la liberación; NO registra el pago como recibido.
const solicitarBloqueo =
  exacta &&
  reconocido &&
  (esTransferencia || pagoSinClaveRastreo) &&
  !fallido;

// Identificador interno de expediente: no es folio, rastreo ni validación bancaria.
const registroSoloRevision = solicitarBloqueo && !huella;
if (registroSoloRevision) {
  huella = ['revision_pendiente', text(d.reserva_draft_id), text(d.subscriber_id)].join('|');
}

return [{
  json: {
    ...d,
    nombre: nombreCliente,
    nombre_reserva: nombreCliente,

    fecha_actual_mexico: fechaActual,
    fecha_pago: fecha,
    fecha_pago_es_hoy: fechaHoy,
    fecha_pago_admisible: fechaAdmisible,
    monto_pago: Number.isFinite(monto) ? monto : null,
    moneda_pago: moneda,

    tipo_cuenta_beneficiaria:
      esClabe ? 'CLABE' : esCuenta ? 'CUENTA' : 'DESCONOCIDA',

    cuenta_beneficiaria_visible: raw,
    cuenta_beneficiaria_enmascarada: enmascarada,
    cuenta_beneficiaria_extraida: completa ? numero : '',
    ultimos_digitos_beneficiario: ultimosVisibles,
    ultimos_4_beneficiario:
      finalVisible && numero.length >= 4 ? numero.slice(-4) : '',

    banco_beneficiario_coincide: bancoOK,
    titular_beneficiario_coincide: titularOK,
    titular_basico_para_nota: titularBasicoOK,
    beneficiario_coincide: beneficiarioOK,
    destino_compatible: destinoCompatible,
    coincidencia_parcial_destino: parcialOK || sufijoOK,

    nombre_cliente_comprobante_coincide: clienteCoincide,
    nombre_cliente_conflicto: clienteConflicto,
    pago_de_tercero: pagoDeTercero,
    nota_pago_de_tercero: notaPagoDeTercero,

    // Es el destino configurado para la consulta, no una CLABE leída
    // de la imagen cuando el comprobante solo muestra un sufijo.
    cuenta_beneficiaria: destinoCompatible ? cfg.clabe : '',
    cuenta_beneficiaria_fuente: !destinoCompatible
      ? 'no_corroborrada'
      : fullOK && esClabe
        ? 'visible_completa'
        : 'configuracion_destino_con_cotejo_visible',

    clave_rastreo: trace,
    numero_referencia: refBanco,
    huella_comprobante: text(d.huella_comprobante_previa) || huella,
    huella_bancaria_calculada: huella,
    registro_solo_revision: registroSoloRevision,

    solicitar_bloqueo: solicitarBloqueo,
    consultar_banxico: consultar && !registroSoloRevision,
    comprobante_visual_corrobora: visual,
    comprobante_basico_para_nota: notaBasica,
    comprobante_manual_sin_rastreo: comprobanteManualSinRastreo,
    pago_sin_clave_rastreo_para_revision: pagoSinClaveRastreo,
    aprobacion_manual_por_folio: aprobacionManualPorFolio,
    folio_operacion: folioOperacion,
    comprobante_corrobora_datos: beneficiarioOK,

    // Solo la respuesta bancaria validada puede cambiar este valor.
    pago_verificado: false,
    motivos_revision_pago: reasons,
    comprobante_estado: liberadaSinCitas
      ? 'revision_manual_liberada'
      : consultar
      ? 'consulta_banxico'
      : pagoSinClaveRastreo
        ? 'revision_manual_sin_rastreo'
        : visual
          ? 'corroborado_visual'
          : 'revision',
  },
}];

const d = $input.first().json ?? {};
// Un mensaje de coqueteo no es una respuesta de pago: no se le pide la clave de
// rastreo. Si el contenido era sexual, el flujo ya cerró y pausó la conversación.
let coqueteoLeve = d._coqueteo_leve === true;
try { coqueteoLeve = coqueteoLeve || $('Detectar contenido sexual y coqueteo').first().json._coqueteo_leve === true; } catch (e) {}
if (coqueteoLeve) {
  return [{json:{...d,datos_pago_solicitados:false,coqueteo_respondido:true,
    estado_pago_cliente:d.estado_pago_cliente ?? d.datos?.estado_cliente_pago ?? null,
    output:{data:[
      {field_name:'Parte 1',field_value:'Con gusto te ayudo con tu reserva ðŸ˜Š'},
      {field_name:'Parte 2',field_value:'Como asesora virtual no puedo tener conversaciones personales ni compartir datos de quien te atiende. Cuando tengas el comprobante o la clave de rastreo, lo revisamos por aquí. ðŸŒ¿'},
    ]}}}];
}
