const normalizar = (v) => String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const faltantesOrigen = Array.isArray(d.datos_a_solicitar) ? d.datos_a_solicitar : (Array.isArray(d.faltantes) ? d.faltantes : []);
const razones = Array.isArray(d.motivos_revision_pago) ? d.motivos_revision_pago : [];
