return [{json:{...d,
  transferencia_asesor_enviada:false,
  revision_manual_solicitada:(revisionManual||tieneIdentificadorMensaje)&&!hayFaltantes,
  aprobacion_manual_por_folio:aprobacionManualPorFolioMensaje,
