// Un turno puede traer varios audios; se unen en un solo turno de texto para el bot.
const entradas = $input.all();
const originales = $('Clasificar archivo descargado').all()
  .map((item) => item.json ?? {})
  .filter((json) => json.es_audio_transcribible === true);

function primerTexto(valor, profundidad = 0) {
  if (profundidad > 6 || valor === null || valor === undefined) return '';
  if (typeof valor === 'string') return valor.trim();
  if (Array.isArray(valor)) {
    for (const item of valor) {
      const hallado = primerTexto(item, profundidad + 1);
      if (hallado) return hallado;
    }
    return '';
  }
  if (typeof valor === 'object') {
    for (const clave of ['text', 'transcript', 'content', 'output_text', 'data']) {
      if (!Object.prototype.hasOwnProperty.call(valor, clave)) continue;
      const hallado = primerTexto(valor[clave], profundidad + 1);
      if (hallado) return hallado;
    }
  }
  return '';
}

const transcripciones = [];
for (let indice = 0; indice < entradas.length; indice++) {
  const respuesta = entradas[indice].json ?? {};
