  .replace(/\s+/g, ' ')
  .trim();

const bodyOriginal = base.body && typeof base.body === 'object'
  ? base.body
  : {};
const customFields = bodyOriginal.custom_fields && typeof bodyOriginal.custom_fields === 'object'
  ? bodyOriginal.custom_fields
  : {};

const body = {
  ...bodyOriginal,
  last_input_text: transcripcion,
  custom_fields: {
    ...customFields,
    Respuesta_definitiva: transcripcion,
  },
};

return [{
  json: {
    ...base,
    body,
    chatInput: transcripcion,
    Respuesta_definitiva: transcripcion,
    texto_usuario: transcripcion,
    transcripcion_audio: transcripcion,
    audio_transcrito_ok: transcripcion.length > 0,
    tipo_entrada: 'audio_transcrito',
    audio_original_url: base.media_url ?? '',
    media_url: '',
    tipo_media_hint: '',
    es_archivo_manychat: false,
    es_audio_manychat: true,
    audios_transcritos: transcripciones.length,
  },
}];

const d = $input.first().json ?? {};
return [{
  json: {
    ...d,
    listo_para_bot: true,
  },
}];

