function texto(valor) {
  return String(valor ?? '').trim();
}

function numeroMoneda(valor) {
  if (typeof valor === 'number') return Number.isFinite(valor) ? valor : null;
  let limpio = texto(valor).replace(/[^0-9,.-]/g, '');
  if (!limpio) return null;
  if (limpio.includes(',') && limpio.includes('.')) limpio = limpio.replace(/,/g, '');
  else if (limpio.includes(',') && !limpio.includes('.')) limpio = limpio.replace(',', '.');
  const numero = Number(limpio);
  return Number.isFinite(numero) ? numero : null;
}

function normalizarSucursal(valor) {
  const original = texto(valor);
  const clave = original.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  const mapa = {
    '24077': '24077', valle: '24077', 'del valle': '24077',
    '24079': '24079', polanco: '24079', polanquito: '24079',
    '24080': '24080', juarez: '24080', 'centro juarez': '24080',
    '24082': '24082', lomas: '24082', 'lomas de chapultepec': '24082',
    '24221': '24221', roma: '24221', 'roma norte': '24221',
  };
  return mapa[clave] || original;
}

const pagoVerificado = banxico.pago_verificado === true && banxico.validacion_banxico_para_solicitud === true;
if (!pagoVerificado) throw new Error('Se intentó confirmar una transferencia que Banxico no marcó como verificada');

const montoPagado = numeroMoneda(
  banxico.monto_pagado ?? banxico.monto_pago ?? banxico.monto ?? reserva.monto_pagado
);
if (!(montoPagado > 0)) throw new Error('Banxico confirmó el pago, pero no devolvió un monto válido');

const reservaDraftId = texto(banxico.reserva_draft_id ?? reserva.reserva_draft_id ?? reserva.id);
if (!reservaDraftId) throw new Error('Banxico confirmó el pago, pero falta reserva_draft_id');

const sucursal = normalizarSucursal(reserva.sucursal ?? banxico.sucursal);
