function texto(valor) {
  return String(valor ?? '').trim();
}

function normalizar(valor) {
  return texto(valor)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[_-]+/g, ' ')
    .replace(/\s+/g, ' ')
    .toLowerCase();
}

function booleano(valor, porDefecto = false) {
  if (valor === undefined || valor === null || valor === '') return porDefecto;
  if (typeof valor === 'boolean') return valor;
  return ['1', 'true', 'si', 'sí', 'yes', 'paid', 'confirmado'].includes(normalizar(valor));
}

function primeraFechaHora(...valores) {
  for (const valor of valores) {
    const limpio = texto(valor);
    if (limpio) return limpio;
  }
  return '';
}

function componentesFechaHora(valor) {
  const match = texto(valor).match(/^(\d{4})-(\d{2})-(\d{2})(?:[T\s](\d{1,2}):(\d{2}))?/);
  if (!match) return { fecha: texto(valor), hora: '' };

  const anio = Number(match[1]);
  const mes = Number(match[2]);
  const dia = Number(match[3]);
  const dias = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
  const meses = [
    'enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio',
    'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre',
  ];
  const diaSemana = dias[new Date(Date.UTC(anio, mes - 1, dia)).getUTCDay()];

  let hora = '';
  if (match[4] !== undefined) {
    const hh24 = Number(match[4]);
    const mm = match[5];
    const periodo = hh24 >= 12 ? 'p. m.' : 'a. m.';
    const hh12 = hh24 % 12 || 12;
    hora = `${hh12}:${mm} ${periodo}`;
  }

  return {
    fecha: `${diaSemana} ${dia} de ${meses[mes - 1]} de ${anio}`,
    hora,
  };
}

function agregarLinea(lineas, etiqueta, valor) {
  const limpio = texto(valor);
  if (limpio) lineas.push(`${etiqueta}: ${limpio}`);
}

