function extraerUrls(cadena) {
  const coincidencias = cadena.match(/https:\/\/[^\s<>"']+/gi) ?? [];
  return coincidencias
    .map((url) => url.replace(/[\]})>,.;!?]+$/g, ''))
    .filter(Boolean);
}

function analizarUrl(urlTexto) {
  const hostMatch = /^https:\/\/([^/?#]+)(?:[/?#]|$)/i.exec(urlTexto);
  if (!hostMatch) return null;

  const host = hostMatch[1].toLowerCase().replace(/\.$/, '');
  if (!hostsPermitidos.has(host)) return null;

  const resto = urlTexto.replace(/^https:\/\/[^/]+/i, '');
  const ruta = (resto.split(/[?#]/, 1)[0] || '/').toLowerCase();
  const esRutaManyChat =
    (host === 'lookaside.fbsbx.com' && ruta.startsWith('/ig_messaging_cdn/')) ||
    host === 'manybot-files.s3.eu-central-1.amazonaws.com' ||
    host === 'manybot-files.manychat.io';
  if (!esRutaManyChat) return null;

  let tipoHint = 'desconocido';
  if (ruta.endsWith('/image') || /\.(?:png|jpe?g|webp|gif|heic|heif)$/.test(ruta)) {
    tipoHint = 'imagen';
  } else if (
    ruta.endsWith('/pdf') ||
    ruta.endsWith('/document') ||
    /\.pdf$/.test(ruta)
  ) {
    tipoHint = 'pdf';
  } else if (
    ruta.endsWith('/audio') ||
    ruta.endsWith('/voice') ||
    /\.(?:flac|mp3|mp4|mpeg|mpga|m4a|ogg|wav|webm)$/.test(ruta)
  ) {
    tipoHint = 'audio';
  }

  return { url: urlTexto, host, ruta, tipoHint };
}

